working:
:root {
  /* TODO 3: Change the accent color. Choose a dark color so the site name stays easy to read. */
  --accent: #06090f;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: #faf9f5;
  color: #292b27;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16px;
  line-height: 1.7;
}

.page-width {
  width: 90%;
  max-width: 820px;
  margin: 0 auto;
}

.site-header {
  padding: 20px 0;
  border-bottom: 2px solid var(--accent);
}

.wordmark {
  margin: 0;
  color: var(--accent);
  font-size: 20px;
  font-weight: bold;
}

.intro {
  padding: 36px 0 28px;
}

.subtitle {
  margin: 0 0 12px;
  color: #62645c;
  font-size: 13px;
}

h1 {
  margin: 0 0 16px;
  font-size: 32px;
  line-height: 1.2;
}

h2 {
  margin: 0 0 10px;
  font-size: 20px;
  line-height: 1.4;
}

p {
  margin: 0 0 12px;
}

.fish-note {
  padding: 22px 26px;
  border-left: 4px solid var(--accent);
  background-color: #efede3;
}

.fish-note p {
  margin: 0;
}

.fish {
  padding: 32px 0;
}

.fish-list {
  margin: 16px 0;
  padding-left: 22px;
}

.fish-list li {
  padding: 4px 0;
}

.site-footer {
  padding: 18px 0 26px;
  border-top: 1px solid #d4d4ca;
  color: #62645c;
  font-size: 13px;
}

.site-footer p {
  margin: 0;
}

@media (max-width: 500px) {
  h1 {
    font-size: 30px;
  }

  .fish-note {
    padding: 18px;
  }
}
